29. 
30. const STANDARD_LANGUAGE_TAGS = new Set(["javascript", "js", "jsx"]);
31. 
32. const commentParser = new ConfigCommentParser();
33. 
34. /**
35.  * Tries to parse a specified JavaScript code with Playground presets.
36.  * @param {string} code The JavaScript code to parse.
37.  * @param {ParserOptions} parserOptions Explicitly specified parser options.
38.  * @returns {{ ast: ASTNode } | { error: SyntaxError }} An AST with comments, or a `SyntaxError` object if the code cannot be parsed.
39.  */
40. function tryParseForPlayground(code, parserOptions) {
41.     try {
42.         const ast = parse(code, { ecmaVersion: "latest", ...parserOptions, comment: true });
43. 
44.         return { ast };
45.     } catch (error) {
46.         return { error };
47.     }
48. }
