50. /**
51.  * Checks the example code blocks in a rule documentation file.
52.  * @param {string} filename The file to be checked.
53.  * @returns {Promise<LintMessage[]>} A promise of problems found. The promise will be rejected if an error occurs.
54.  */
55. async function findProblems(filename) {
56.     const text = await readFile(filename, "UTF-8");
57.     const { title } = matter(text).data;
58.     const isRuleRemoved = !rules.has(title);
59.     const problems = [];
60.     const ruleExampleOptions = markdownItRuleExample({
61.         open({ code, parserOptions, codeBlockToken }) {
62.             const languageTag = codeBlockToken.info;
63. 
64.             if (!STANDARD_LANGUAGE_TAGS.has(languageTag)) {
65. 
66.                 /*
67.                  * Missing language tags are also reported by Markdownlint rule MD040 for all code blocks,
68.                  * but the message we output here is more specific.
69.                  */
70.                 const message = `${languageTag
71.                     ? `Nonstandard language tag '${languageTag}'`
72.                     : "Missing language tag"}: use one of 'javascript', 'js' or 'jsx'`;
73. 
74.                 problems.push({
75.                     fatal: false,
76.                     severity: 2,
77.                     message,
78.                     line: codeBlockToken.map[0] + 1,
79.                     column: codeBlockToken.markup.length + 1
80.                 });
81.             }
82. 
83.             const { ast, error } = tryParseForPlayground(code, parserOptions);
84. 
85.             if (ast && !isRuleRemoved) {
86.                 const hasRuleConfigComment = ast.comments.some(
87.                     comment => {
88.                         if (comment.type !== "Block" || !/^\s*eslint(?!\S)/u.test(comment.value)) {
89.                             return false;
90.                         }
91.                         const { directiveValue } = commentParser.parseDirective(comment);
92.                         const parseResult = commentParser.parseJsonConfig(directiveValue, comment.loc);
93. 
94.                         return parseResult.success && Object.prototype.hasOwnProperty.call(parseResult.config, title);
95.                     }
96.                 );
97. 
98.                 if (!hasRuleConfigComment) {
99.                     const message = `Example code should contain a configuration comment like /* eslint ${title}: "error" */`;
100. 
101.                     problems.push({
102.                         fatal: false,
103.                         severity: 2,
104.                         message,
105.                         line: codeBlockToken.map[0] + 2,
106.                         column: 1
107.                     });
108.                 }
109.             }
110. 
111.             if (error) {
112.                 const message = `Syntax error: ${error.message}`;
113.                 const line = codeBlockToken.map[0] + 1 + error.lineNumber;
114.                 const { column } = error;
115. 
116.                 problems.push({
117.                     fatal: false,
118.                     severity: 2,
119.                     message,
120.                     line,
121.                     column
122.                 });
123.             }
124.         }
125.     });
126. 
127.     // Run `markdown-it` to check rule examples in the current file.
128.     markdownIt({ html: true })
129.         .use(markdownItContainer, "rule-example", ruleExampleOptions)
130.         .render(text);
131.     return problems;
132. }
